<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){fwrite(STDERR,"Partners tests are CLI-only.\n");exit(1);} $root=dirname(__DIR__);
spl_autoload_register(static function(string$class)use($root):void{$p='Babanoell\\Partners\\';if(!str_starts_with($class,$p))return;$f=$root.'/src/'.str_replace('\\','/',substr($class,strlen($p))).'.php';if(is_file($f))require$f;});
$tests=[];$add=static function(string$n,callable$f)use(&$tests){$tests[$n]=$f;};$assert=static function(bool$v,string$m='assertion failed'){if(!$v)throw new RuntimeException($m);};$eq=static function(mixed$a,mixed$b){if($a!==$b)throw new RuntimeException(var_export($a,true).' !== '.var_export($b,true));};

$add('release identifies Partners 1.0.0',function()use($root,$eq){$v=require$root.'/config/version.php';$eq('partners',$v['service']);$eq('1.0.0',$v['version']);$eq('partners-service',$v['phase']);});
$add('service boundary owns merchant cooperation and marketplace domains',function()use($assert){$c=Babanoell\Partners\Platform\ServiceBoundary::describe();foreach(['merchants','merchant_memberships','merchant_plan_permissions','cooperation_requests','marketplace_orchestration']as$x)$assert(in_array($x,$c['owns'],true));foreach(['identity','loans','documents']as$x)$assert(in_array($x,$c['depends_on'],true));});
$add('service boundary forbids loan finance and binary document ownership',function()use($assert){$c=Babanoell\Partners\Platform\ServiceBoundary::describe();foreach(['loan_calculations','loan_status_machine','document_binary_storage','financial_settlement_ledger','provider_credentials']as$x)$assert(in_array($x,$c['forbidden'],true));});
$add('partner rules validate merchant codes and ids',function()use($eq){$eq('MERCHANT_01',Babanoell\Partners\Domain\PartnerRules::merchantCode('merchant_01'));$eq(str_repeat('a',26),Babanoell\Partners\Domain\PartnerRules::id(str_repeat('a',26),'id'));});
$add('cooperation transition map is fail closed',function()use($assert){Babanoell\Partners\Domain\PartnerRules::assertTransition('submitted','under_review');$failed=false;try{Babanoell\Partners\Domain\PartnerRules::assertTransition('approved','submitted');}catch(Throwable){$failed=true;}$assert($failed);});
$add('idempotency contract rejects spaces and short keys',function()use($assert,$eq){$eq('partner:12345678',Babanoell\Partners\Http\IdempotencyKey::normalize(' partner:12345678 '));$failed=false;try{Babanoell\Partners\Http\IdempotencyKey::normalize('bad key');}catch(Throwable){$failed=true;}$assert($failed);});
$add('request context preserves correlation ids',function()use($eq){$eq('req_12345678',Babanoell\Partners\Platform\RequestContext::initialize('req_12345678'));});
$add('service auth signs and verifies Partners calls',function()use($assert){$body='{"a":1}';$h=Babanoell\Partners\Platform\ServiceAuth::outbound('partners','POST','/api/v1/x',$body,'secret');$r=Babanoell\Partners\Platform\ServiceAuth::verify($h['X-Noel-Service'],$h['X-Noel-Timestamp'],$h['X-Noel-Signature'],'POST','/api/v1/x',$body,'secret','required');$assert($r['ok']===true&&$r['authenticated']===true);});
$add('pagination contract is stable',function()use($eq){$eq(['page'=>2,'per_page'=>20,'total'=>41,'total_pages'=>3],Babanoell\Partners\Http\Pagination::fromResult(['page'=>2,'per_page'=>20,'total'=>41]));});
$add('migration files expose three unique versions',function()use($root,$assert,$eq){$files=glob($root.'/database/migrations/*.php')?:[];sort($files);$versions=[];foreach($files as$f){$m=require$f;$assert($m instanceof Babanoell\Partners\Database\Migration);$assert(!isset($versions[$m->version()]));$versions[$m->version()]=1;}$eq(3,count($versions));});
$add('merchant core has no cross service foreign keys',function()use($root,$assert){$s=file_get_contents($root.'/database/migrations/202609290001_create_partner_merchant_core.php');foreach(['REFERENCES users','REFERENCES installment_plans','REFERENCES loan_requests','REFERENCES documents']as$n)$assert(!str_contains($s,$n));$assert(str_contains($s,'merchant_user_memberships'));$assert(str_contains($s,'merchant_plan_permissions'));});
$add('cooperation core stores only document references not binary',function()use($root,$assert){$s=file_get_contents($root.'/database/migrations/202609290002_create_cooperation_core.php');$assert(str_contains($s,'document_id'));$assert(!str_contains(strtolower($s),'longblob'));$assert(!str_contains(strtolower($s),'mediumblob'));});
$add('marketplace claim and invitations have uniqueness and audit tables',function()use($root,$assert){$s=file_get_contents($root.'/database/migrations/202609290003_create_marketplace_and_audit_core.php');foreach(['marketplace_claims','merchant_invitations','partner_events','UNIQUE KEY']as$n)$assert(str_contains($s,$n));});
$add('database isolation guard rejects Identity Loans and Documents markers',function()use($root,$assert){$s=file_get_contents($root.'/src/Database/DatabaseIsolationGuard.php');foreach(['users','roles','installment_plans','loan_requests','documents','document_versions']as$n)$assert(str_contains($s,"'{$n}'"));});
$add('API exposes merchant directory cooperation marketplace and compatibility surface',function()use($root,$assert){$s=file_get_contents($root.'/public/index.php');foreach(['/api/v1/directory/merchants','/api/v1/me/merchant','/api/v1/merchants','/api/v1/cooperation/requests','/api/v1/marketplace/requests','/api/v1/invitations/redeem']as$n)$assert(str_contains($s,$n),$n);});
$add('Partners clients call dependencies through HTTP only',function()use($root,$assert){foreach(['IdentityClient.php','LoansClient.php','DocumentsClient.php']as$f){$s=file_get_contents($root.'/src/Http/'.$f);$assert(str_contains($s,'ServiceAuth::outbound'));}$all='';foreach(glob($root.'/src/**/*.php')?:[]as$f)$all.=file_get_contents($f);$assert(!str_contains($all,'noeelir_loans.'));$assert(!str_contains($all,'noeelir_identity.'));$assert(!str_contains($all,'noeelir_documents.'));});
$add('updater is partners scoped and protects private state',function()use($root,$assert){$s=file_get_contents($root.'/src/Update/UpdateTool.php');$assert(str_contains($s,"'partners/'"));foreach(['config/local.env.php','storage']as$n)$assert(str_contains($s,$n));});
$add('installer writes private config and locks itself',function()use($root,$assert){$s=file_get_contents($root.'/public/install.php');foreach(['config/local.env.php','installed.lock','install.php.locked','PARTNERS_DB_NAME','PARTNERS_IDENTITY_BASE_URL','PARTNERS_LOANS_BASE_URL','PARTNERS_DOCUMENTS_BASE_URL']as$n)$assert(str_contains($s,$n),$n);});
$add('root web rules block private internals',function()use($root,$assert){$s=file_get_contents($root.'/.htaccess');foreach(['config','database','storage','src','tests']as$n)$assert(str_contains($s,$n));});
$add('event audit includes request id and caller service',function()use($root,$assert){$s=file_get_contents($root.'/src/Repository/PdoPartnerRepository.php');$assert(str_contains($s,'RequestContext::auditMeta()'));$assert(str_contains($s,'request_id'));$assert(str_contains($s,'caller_service'));});
$add('marketplace claim in Loans is compare-and-set and privacy safe',function()use($root,$assert){$loans=dirname(dirname($root)).'/loans.noeel.ir/public_html/src/Repository/PdoLoanRepository.php';$s=file_get_contents($loans);$assert(str_contains($s,"marketplace_status='open'"));$assert(str_contains($s,"marketplace_status='claimed'"));$assert(!str_contains(substr($s,strpos($s,'function listMarketplace'),strpos($s,'function claimMarketplace')-strpos($s,'function listMarketplace')),'national_code'));});
$add('dependency health clients use liveness endpoints to prevent readiness cycles',function()use($root,$assert){foreach(['IdentityClient.php','LoansClient.php','DocumentsClient.php']as$f){$s=file_get_contents($root.'/src/Http/'.$f);$assert(str_contains($s,"'/health'"),$f);$assert(!str_contains($s,"'/healthz'"),$f);}});


$pass=0;$fail=0;foreach($tests as$n=>$t){try{$t();echo"[PASS] {$n}\n";$pass++;}catch(Throwable$e){echo"[FAIL] {$n}: {$e->getMessage()}\n";$fail++;}}echo'Partners tests: '.($pass+$fail).' run, '.$fail." failed.\n";exit($fail?1:0);
